using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEngine.SceneManagement;using Demo5.FrontEnd;
public static class VerifyWorktreeIntegration {
 static SettlementController C=>UnityEngine.Object.FindAnyObjectByType<SettlementController>();
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 public static async Task<string> Capture(){Directory.CreateDirectory("Assets/Screenshots/MergeVerification");ScreenCapture.CaptureScreenshot("Assets/Screenshots/MergeVerification/01-integrated-settlement.png");await Task.Delay(650);return "Captured integrated settlement at "+Screen.width+"x"+Screen.height;}
 public static async Task<string> Saves(){var c=C;Check(c&&c.Opening&&c.Opening.State!=null,"Live settlement required");var original=CampaignPersistence.Capture(c);var legacy=JsonUtility.FromJson<CampaignSaveData>(JsonUtility.ToJson(original));legacy.Version=10;legacy.Opening=null;CampaignPersistence.Upgrade(legacy,c);Check(legacy.Version==CampaignPersistence.CurrentVersion&&!legacy.Opening.Enabled&&legacy.Members.Length==original.Members.Length,"v10 migration must preserve party without replaying opening");c.Opening.State=new SavedOpeningChapter{Enabled=true,FirstReturn=true,ClueRead=true,SurveyReturned=true,Complete=true,NightHeard=true,NightChoice=2};var saved=CampaignPersistence.Capture(c);CampaignSaveStore.TestDirectory=Path.GetFullPath("Temp/WorktreeIntegrationSaves");try{Check(CampaignSaveStore.Write(0,saved,c,out var error),error);var read=CampaignSaveStore.Read(0,c);Check(read.CanLoad,read.Error);Check(read.Data.Version==CampaignPersistence.CurrentVersion&&read.Data.Opening.NightChoice==2&&read.Data.Searches.Length==saved.Searches.Length&&read.Data.SiteBoards.Length==saved.SiteBoards.Length,"Opening/field save roundtrip");CampaignPersistence.Prepare(read.Data,c);SceneManager.LoadScene("Settlement");await Task.Delay(700);Check(C.Opening.State.NightChoice==2&&C.ArrivalPanel.Loot.Sites.Length==9&&C.ArrivalPanel.Threat&&C.ArrivalPanel.Threat.Planner,"Merged runtime references");C.Opening.OpenRecords();C.Opening.SelectRecord(3);Directory.CreateDirectory("Assets/Screenshots/MergeVerification");ScreenCapture.CaptureScreenshot("Assets/Screenshots/MergeVerification/02-integrated-records.png");await Task.Delay(650);C.Opening.Close();return "PASS v10 -> v13 migration, party preserved, v13 disk save/read/reload (site boards "+saved.SiteBoards.Length+"), opening/night choice retained, 9 exploration sites and latest threat/planner retained.";}finally{CampaignSaveStore.TestDirectory=null;}}
}
